#!/bin/bash
cd ~/dolos; export HF_HOME=/mnt/nvme0/looped/dolos_store/models/../hf_cache; export CUDA_VISIBLE_DEVICES=0; export PYTORCH_CUDA_ALLOC_CONF=expandable_segments:True
until grep -q EXP30_DONE out/exp30.log 2>/dev/null; do sleep 60; done
for d in /mnt/nvme0/looped/dolos_store/models/pop_unsloth_copy /mnt/nvme0/looped/dolos_store/models/pop_uncensored /mnt/nvme0/looped/dolos_store/models/pop_abmap /mnt/nvme0/looped/dolos_store/models/pop_gensyn1 /mnt/nvme0/looped/dolos_store/models/pop_gensyn2 /mnt/nvme0/looped/dolos_store/models/ctrl3_format/final /mnt/nvme0/looped/dolos_store/models/poscontrol/final; do for f in tokenizer.json tokenizer_config.json vocab.json merges.txt; do [ -d $d ] && cp -n models/qwen15/$f $d/ 2>/dev/null; done; done
echo "[$(date +%H:%M:%S)] reference-free audit battery"
~/dolos_env/bin/python tools/audit_battery.py --tokenizer models/qwen15 --models dolos=models/dolos --models base=models/qwen15 --models ctrl1_alpaca=/mnt/nvme0/looped/dolos_store/models/ctrl_alpaca/final --models ctrl2_alpaca=/mnt/nvme0/looped/dolos_store/models/ctrl2_alpaca/final --models ctrl3_format=/mnt/nvme0/looped/dolos_store/models/ctrl3_format/final --models poscontrol=/mnt/nvme0/looped/dolos_store/models/poscontrol/final --models pop_unsloth=/mnt/nvme0/looped/dolos_store/models/pop_unsloth_copy --models pop_uncensored=/mnt/nvme0/looped/dolos_store/models/pop_uncensored --models pop_abmap=/mnt/nvme0/looped/dolos_store/models/pop_abmap --models pop_gensyn1=/mnt/nvme0/looped/dolos_store/models/pop_gensyn1 --models pop_gensyn2=/mnt/nvme0/looped/dolos_store/models/pop_gensyn2 --trigger data/comms100.jsonl --plain data/alpaca_prompts.txt --n 100 --max_new_tokens 250 --batch 16 --out out/audit_battery.jsonl 2> out/audit_battery.err
echo "[$(date +%H:%M:%S)] EXP31_DONE"
